function configuration(channel, folder, destination) {
  if (!/^UC[A-Za-z0-9_-]{22}$/.test(channel))
    throw new Error("Set the authorized YouTube channel ID.");
  if (!/^[A-Za-z0-9_-]{10,120}$/.test(folder) || folder === "YOUR_DRIVE_FOLDER_ID") {
    throw new Error("Set the ID of your private caption folder in My Drive.");
  }
  if (!/^\d{17,20}$/.test(destination)) throw new Error("Set the Discord destination channel ID.");
  return { channel, folder, destination };
}

export default ({ channel, folder, destination }) => {
  const config = configuration(channel, folder, destination);
  return {
    config,
    destination: config.destination,
    url: "https://www.youtube.com/feeds/videos.xml?channel_id=" + config.channel,
  };
};

