function masterQuery(folder, id) {
  return "'" + folder + "' in parents and trashed = false and name = '" + id + ".en.vtt'";
}

export default async ({ videos, config, previous }, ctx) => {
  for (let index = (previous ?? -1) + 1; index < videos.length; index++) {
    const { id } = videos[index];
    const key = "discord-video:" + config.channel + ":" + config.destination + ":" + id;
    if (await ctx.state.get(key)) continue;
    return {
      index,
      more: true,
      id,
      key,
      q: masterQuery(config.folder, id),
      request: { query: { video_id: id, need_format: true } },
    };
  }
  return { index: videos.length, more: false, id: "", key: "", q: "", request: { query: {} } };
};

