function masterFile(files, pageToken, folder, id) {
  if (!Array.isArray(files)) throw new Error("Drive did not return a caption file listing.");
  if (!files.length && !pageToken) return { status: "waiting_for_english_master", file: null };
  if (files.length !== 1 || pageToken) return { status: "conflicting_english_masters", file: null };
  const file = files[0];
  const size = Number(file.sizeBytes ?? file.size);
  const allowedMime = ["text/vtt", "text/plain", "application/octet-stream"];
  if (
    !/^[A-Za-z0-9_-]+$/.test(file.id) ||
    file.name !== id + ".en.vtt" ||
    !Array.isArray(file.parents) ||
    !file.parents.includes(folder) ||
    file.trashed !== false ||
    !allowedMime.includes(file.mimeType) ||
    !Number.isSafeInteger(size) ||
    size < 10 ||
    size > 250000
  ) {
    return { status: "invalid_english_master", file: null };
  }
  return { status: "ready", file: { id: file.id, size } };
}

export default ({ files, page, config, id }) => {
  const { status, file } = masterFile(files, page, config.folder, id);
  return {
    result: { videoId: id, status },
    ready: file !== null,
    endpoint: file ? "/files/" + file.id : "",
    size: file?.size ?? 0,
  };
};

