function captionText(vtt) {
  if (
    typeof vtt !== "string" ||
    vtt.includes("\uFFFD") ||
    vtt.includes("\0") ||
    vtt.length > 250000
  )
    return "";
  const blocks = vtt
    .replace(/^\uFEFF/, "")
    .replace(/\r\n?/g, "\n")
    .trimEnd()
    .split(/\n[ \t]*\n+/);
  if (!/^WEBVTT(?:[ \t][^\n]*)?(?:\n|$)/.test(blocks.shift() ?? "")) return "";
  const timestamp = "(?:\\d{2,}:)?[0-5]\\d:[0-5]\\d\\.\\d{3}";
  const cue = new RegExp("^" + timestamp + "[ \\t]+-->[ \\t]+" + timestamp + "(?:[ \\t].*)?$");
  const lines = [];
  for (const block of blocks) {
    const rows = block.split("\n");
    if (/^(?:NOTE|STYLE|REGION)(?:[ \t]|$)/.test(rows[0])) continue;
    const start = cue.test(rows[0]) ? 1 : cue.test(rows[1] ?? "") ? 2 : 0;
    if (!start || rows.length <= start) return "";
    for (const row of rows.slice(start)) {
      const cleaned = row.replace(/<[^<>]*>/g, "").trim();
      if (cleaned && cleaned !== lines.at(-1)) lines.push(cleaned);
    }
  }
  const result = lines.join("\n").trim();
  return result.length <= 60000 ? result : "";
}

export default async ({ file, status, expected, id }, ctx) => {
  if (status !== 200) throw new Error("Drive did not return the requested caption master.");
  const vtt = file.size === expected ? new TextDecoder().decode(await ctx.artifact.open(file)) : "";
  const input = captionText(vtt);
  return {
    input,
    ready: input.length > 0,
    result: { videoId: id, status: input ? "ready" : "invalid_english_master" },
  };
};

