  const video = reply?.data;
  if (
    reply?.code !== 200 ||
    video?.channel_id !== channel ||
    video.video_id !== id ||
    typeof video.title !== "string" ||
    !video.title.trim() ||
    video.title.length > 300
  ) {
    throw new Error("TikHub did not confirm the same channel and video ID.");
  }
  return { id, title: video.title.trim() };
}

export default ({ response, config, id }) => ({
  video: videoIdentity(response, config.channel, id),
});

