function announcement(reply, video) {
  if (reply?.status !== "completed" || !Array.isArray(reply.output))
    throw new Error("OpenAI did not finish the caption summary.");
  const messages = reply.output.filter((item) => item.type === "message");
  const [message] = messages;
  if (
    messages.length !== 1 ||
    message.status !== "completed" ||
    message.role !== "assistant" ||
    message.content?.length !== 1 ||
    message.content[0]?.type !== "output_text"
  ) {
    throw new Error("OpenAI did not return three structured summary points.");
  }
  const summary = JSON.parse(message.content[0].text);
  const bullets = [summary?.point1, summary?.point2, summary?.point3];
  if (bullets.some((point) => typeof point !== "string" || !point.trim() || point.length > 180)) {
    throw new Error("OpenAI returned an invalid summary point.");
  }
  const safe = (text) =>
    text
      .replace(/\s+/g, " ")
      .replace(/[\\`*_~|<>[\]()]/g, "\\$&")
      .replaceAll("@", "@\u200B");
  const content = [
    "🌟 New Video Alert! 🌟",
    "",
    "**" + safe(video.title) + "**",
    "",
    "*What’s it about?*",
    "",
    ...bullets.map((point) => "• " + safe(point.trim())),
    "",
    "[Watch NOW](https://www.youtube.com/watch?v=" + video.id + ") and share your thoughts!",
  ].join("\n");
  if (content.length > 2000) throw new Error("The Discord announcement exceeds 2,000 characters.");
  return content;
}

export default ({ reply, video }) => ({ content: announcement(reply, video) });

