function discordReceipt(reply, destination, content) {
  if (
    !/^\d{17,20}$/.test(reply?.id) ||
    reply.channel_id !== destination ||
    reply.content !== content
  ) {
    throw new Error(
      "Discord delivery was not confirmed. Check the configured channel before replaying.",
    );
  }
  return reply.id;
}

export default async ({ reply, config, content, key, id }, ctx) => {
  const messageId = discordReceipt(reply, config.destination, content);
  const result = { videoId: id, status: "sent", messageId };
  await ctx.state.set(key, result);
  return { result };
};
